// Package toolutil holds small pieces of tool-registration infrastructure
// shared across the tool and prompt surfaces. Today that is only the icon set
// below; it exists as its own package so cmd/server, internal/tools and
// internal/prompts can all reach it without an import cycle.
package toolutil

import (
	"embed"
	"encoding/base64"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// webpFS embeds the lossless WebP fallbacks generated by cmd/gen_icon_webp
// from the SVG constants below. Regenerate with `go run ./cmd/gen_icon_webp/`
// (or `make gen-icon-webp`) after adding or editing an icon.
//
//go:embed icons/webp/*.webp
var webpFS embed.FS

// Brand icon: the same open-book-and-arrow mark published at
// site/src/assets/logo-{light,dark}.svg, merged into one currentColor path
// instead of copying either theme variant.
//
// That merge is possible because the three sub-paths (the arrow, the left
// page, the right page) are each already a separate closed shape — they were
// given three different fill colors for visual depth, not because any one of
// them needs another to close. A currentColor render loses that depth but
// keeps the exact outline; verified by rendering both side by side before
// this replaced the two-file version.
//
// Keeping the SVG itself themeless still matters for size: under SEP-2575
// the whole Implementation — Icons included — rides in the `_meta` of every
// response, not just the handshake, so a hand-authored light/dark SVG pair
// would have doubled the largest entry's recurring cost for no benefit a
// currentColor render doesn't already give. The light/dark WebP fallbacks
// [icon] adds are a different trade: they are 16×16 rasters of a few hundred
// bytes each, and they buy an icon in clients that reject SVG outright.
const svgBrand = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" role="img" aria-label="libgen-mcp"><path fill="currentColor" d="M28 8 h8 v14 h8 L32 36 20 22 h8 z M32 39 C22 34 12 34 6 38 L6 51 C12 47 22 47 32 52 Z M32 39 C42 34 52 34 58 38 L58 51 C52 47 42 47 32 52 Z"/></svg>`

// Feature icons: one per tool and one per prompt, each a single-color
// currentColor SVG so its SVG entry renders correctly against any client
// theme without a hand-authored light/dark pair. [icon] adds the rasterized
// WebP fallbacks for clients that will not take an SVG at all.
const (
	svgSearch               = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><circle cx="6.5" cy="6.5" r="4.5" fill="none" stroke="currentColor" stroke-width="1.5"/><line x1="10" y1="10" x2="14.5" y2="14.5" stroke="currentColor" stroke-width="1.5"/></svg>`
	svgDetails              = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><circle cx="8" cy="8" r="6.5" fill="none" stroke="currentColor" stroke-width="1.5"/><line x1="8" y1="7" x2="8" y2="11.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><circle cx="8" cy="4.5" r="1" fill="currentColor"/></svg>`
	svgDownload             = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M8 1.5v8m-3-3l3 3 3-3"/><line x1="2.5" y1="13.5" x2="13.5" y2="13.5"/></svg>`
	svgRead                 = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><path fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round" d="M8 3C6 1.8 3.5 1.8 2 2.5v9.5c1.5-.7 4-.7 6 .5 2-1.2 4.5-1.2 6-.5V2.5C12.5 1.8 10 1.8 8 3z"/><line x1="8" y1="3" x2="8" y2="12.5" stroke="currentColor" stroke-width="1.3"/></svg>`
	svgAcquireBook          = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><rect x="3" y="2" width="10" height="12" rx="1" fill="none" stroke="currentColor" stroke-width="1.5"/><line x1="6" y1="2" x2="6" y2="14" stroke="currentColor" stroke-width="1.2"/><path fill="currentColor" d="M9.5 2v5l1.5-1.2L12.5 7V2"/></svg>`
	svgResearchTopic        = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><rect x="2" y="4" width="9" height="10" rx="1" fill="none" stroke="currentColor" stroke-width="1.3"/><rect x="5" y="1.5" width="9" height="10" rx="1" fill="none" stroke="currentColor" stroke-width="1.3"/><line x1="7" y1="4.5" x2="12" y2="4.5" stroke="currentColor" stroke-width="1"/></svg>`
	svgGetPaper             = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><path fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round" d="M3.5 1.5h6l3 3v10h-9z"/><path fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round" d="M9.5 1.5v3h3"/><line x1="5.5" y1="9" x2="10.5" y2="9" stroke="currentColor" stroke-width="1" stroke-linecap="round"/><line x1="5.5" y1="11.3" x2="9" y2="11.3" stroke="currentColor" stroke-width="1" stroke-linecap="round"/></svg>`
	svgDownloadTroubleshoot = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" stroke-linecap="round"><path d="M11 2.5a3 3 0 0 0-3.9 3.9L2 11.5 4.5 14l5.1-5.1a3 3 0 0 0 3.9-3.9l-2 2-1.5-.5-.5-1.5z"/></svg>`
)

const (
	svgMIME  = "image/svg+xml"
	webpMIME = "image/webp"
)

// icon wraps an SVG string and its pre-rasterized WebP fallbacks as an
// [mcp.Icon] slice with base64-encoded data URIs. Base64 encoding is required
// because raw SVG markup contains characters (<, >, ", spaces, #) that are
// not valid in an unencoded RFC 2397 data URI; the MCP spec also documents
// base64 as the canonical form for embedded image data.
//
// name identifies the WebP pair embedded at icons/webp/<name>-light.webp and
// icons/webp/<name>-dark.webp (generated by cmd/gen_icon_webp). The slice has
// three entries:
//
//   - SVG, Sizes ["any"], no Theme — resolution-independent, adapts to any
//     client theme via currentColor. Used by clients that accept SVG.
//   - WebP, Sizes ["16x16"], Theme "light" — near-black glyph for a light
//     background.
//   - WebP, Sizes ["16x16"], Theme "dark" — near-white glyph for a dark
//     background.
//
// The raster pair exists because a client can support icons and still refuse
// this one: VS Code Copilot's MIME allowlist admits image/webp but not
// image/svg+xml, so an SVG-only icon silently failed to render there. A
// client that accepts SVG keeps getting the scalable entry first and can
// ignore the rest.
func icon(name, svg string) []mcp.Icon {
	encodedSVG := base64.StdEncoding.EncodeToString([]byte(svg))
	return []mcp.Icon{
		{
			Source:   "data:" + svgMIME + ";base64," + encodedSVG,
			MIMEType: svgMIME,
			Sizes:    []string{"any"},
		},
		webpIcon(name, "light", mcp.IconThemeLight),
		webpIcon(name, "dark", mcp.IconThemeDark),
	}
}

// webpIcon reads the embedded icons/webp/<name>-<variant>.webp asset and
// wraps it as an [mcp.Icon]. It panics on a missing or unreadable asset:
// every svg<Name> constant must have a matching WebP pair generated by
// cmd/gen_icon_webp, so a mismatch is a build-time programming error, not a
// runtime condition to recover from.
func webpIcon(name, variant string, theme mcp.IconTheme) mcp.Icon {
	data, err := webpFS.ReadFile(fmt.Sprintf("icons/webp/%s-%s.webp", name, variant))
	if err != nil {
		panic(fmt.Sprintf("toolutil: missing embedded icon asset for %q (%s): %v — run `go run ./cmd/gen_icon_webp/`", name, variant, err))
	}
	return mcp.Icon{
		Source:   "data:" + webpMIME + ";base64," + base64.StdEncoding.EncodeToString(data),
		MIMEType: webpMIME,
		Sizes:    []string{"16x16"},
		Theme:    theme,
	}
}

// IconBrand identifies the server itself on the MCP Implementation
// (serverInfo), as opposed to any one tool or prompt. Everything below it is
// a domain icon: one per tool (IconSearch, IconDetails, IconDownload,
// IconRead) and one per prompt (IconAcquireBook, IconResearchTopic,
// IconGetPaper, IconDownloadTroubleshoot).
//
// Each is a three-element []mcp.Icon: the scalable SVG plus its light/dark
// WebP fallback. The name argument keys the embedded raster pair and must
// match the svg<Name> constant's suffix, lowercased — that is the mapping
// cmd/gen_icon_webp writes the files under.
var (
	IconBrand                = icon("brand", svgBrand)
	IconSearch               = icon("search", svgSearch)
	IconDetails              = icon("details", svgDetails)
	IconDownload             = icon("download", svgDownload)
	IconRead                 = icon("read", svgRead)
	IconAcquireBook          = icon("acquirebook", svgAcquireBook)
	IconResearchTopic        = icon("researchtopic", svgResearchTopic)
	IconGetPaper             = icon("getpaper", svgGetPaper)
	IconDownloadTroubleshoot = icon("downloadtroubleshoot", svgDownloadTroubleshoot)
)
